<script setup lang="ts">import { onMounted, ref } from "vue"; import { lowStock, type Item } from "../api"; const items = ref<Item[]>([]); onMounted(async () => { items.value = await lowStock(); });</script><template><section><header><div><p class="eyebrow">Almacen</p><h1>Alertas de stock</h1></div></header><div class="customer-list"><p v-if="!items.length" class="empty">No hay alertas de stock bajo.</p><RouterLink v-else v-for="item in items" :key="item.id" class="customer-row" :to="{ name: 'inventory.detail.general', params: { id: item.id } }"><strong>{{ item.name }}</strong><span>{{ item.sku }}</span><span>{{ item.stock }} {{ item.unit }}</span><span class="status-pill">Min. {{ item.minimumStock }}</span></RouterLink></div></section></template>